package net.atlasauth.pca;

import static org.junit.jupiter.api.Assertions.*;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import org.junit.jupiter.api.Test;

/**
 * 0.4.2 mutation kills for IntentWB.java (the W-B unit, rules 16-18): every case of test-data/k042-wbmisc.json.gz (the TS
 * reference decideIntentWB, generated by tools/pca-audit/java-mutate/k042-wbmisc-oracle.mjs) compares the FULL Java result
 * with the reference: outcome, checks in order, exact reason, friction, world / prov / class env members and single_source
 * (all cleared on deny, the Java Result contract).
 */
public class K042WbPcaMiscWbTest {
    @SuppressWarnings("unchecked")
    static List<Object> cases() throws Exception {
        try (InputStream in = new GZIPInputStream(Files.newInputStream(Path.of("test-data/k042-wbmisc.json.gz")))) {
            Map<String, Object> doc = (Map<String, Object>) Json.parseLenient(new String(in.readAllBytes(), StandardCharsets.UTF_8));
            return (List<Object>) doc.get("cases");
        }
    }

    static Map<String, Object> got(IntentWB.Result r) {
        Map<String, Object> g = new LinkedHashMap<>();
        g.put("outcome", r.outcome);
        List<Object> checks = new ArrayList<>();
        for (Map.Entry<String, String> e : r.checks.entrySet()) checks.add(List.of(e.getKey(), e.getValue()));
        g.put("checks", checks);
        g.put("reason", r.reason);
        g.put("friction", r.friction);
        g.put("world", r.world);
        g.put("prov", r.prov);
        g.put("class", r.cls);
        g.put("single_source", r.singleSource == null ? null : new ArrayList<Object>(r.singleSource));
        return g;
    }

    /**
     * One known, deny-preserving divergence of the fail-closed evaluation-error text (not IntentWB's): Java reports the
     * exception class where TS reports its message. Everything else (outcome, checks, env) must still match. (An absent
     * {@code aud} is no longer an evaluation error: rule 17 prints it as 'undefined', as TS does.)
     */
    static final Map<String, String> EVAL_ERROR_TEXT = Map.of(
        "lift/cls/content-too-deep", "classes: evaluation error (fail closed): IllegalArgumentException");

    static List<Object> CACHE;

    static synchronized List<Object> all() throws Exception {
        if (CACHE == null) CACHE = cases();
        return CACHE;
    }

    /** Run every case whose name starts with one of {@code prefixes}; returns the count. */
    @SuppressWarnings("unchecked")
    static int run(String... prefixes) throws Exception {
        List<String> bad = new ArrayList<>();
        int n = 0;
        for (Object o : all()) {
            Map<String, Object> c = (Map<String, Object>) o;
            String name = (String) c.get("name");
            boolean mine = false;
            for (String p : prefixes) mine |= name.startsWith(p);
            if (!mine) continue;
            n++;
            Map<String, Object> input = IntentJs.obj(IntentJs.normalize(c.get("input")));
            IntentWB.Result r;
            try {
                r = IntentWB.decide(input);
            } catch (RuntimeException e) {
                bad.add(name + ": threw " + e);
                continue;
            }
            if (r == null) { bad.add(name + ": null result"); continue; }
            Map<String, Object> want = (Map<String, Object>) IntentJs.normalize(c.get("expect"));
            if (EVAL_ERROR_TEXT.containsKey(name)) {
                want = new LinkedHashMap<>(want);
                want.put("reason", EVAL_ERROR_TEXT.get(name));
            }
            String w = Json.canonicalize(want);
            String have = Json.canonicalize(got(r));
            if (!w.equals(have)) bad.add(name + "\n   want " + w + "\n   have " + have);
        }
        assertEquals(List.of(), bad, bad.size() + " mismatches");
        return n;
    }

    @Test void contextShape() throws Exception { assertTrue(run("ctx/", "wb/ctx-") > 60); }
    @Test void goUnitCases() throws Exception { assertTrue(run("wb/") >= 30); }
    @Test void liftedWorld() throws Exception { assertTrue(run("lift/world/") > 100); }
    @Test void liftedProvenance() throws Exception { assertTrue(run("lift/prov/") > 100); }
    @Test void liftedClassifiers() throws Exception { assertTrue(run("lift/cls/") > 40); }
    @Test void droppedMembers() throws Exception { assertTrue(run("drop-", "other-") > 150); }
    @Test void denyClearsEarlierEnv() throws Exception { assertTrue(run("then-") >= 20); }

    @Test
    @SuppressWarnings("unchecked")
    void everyCaseIsRun() throws Exception {
        int total = 0;
        for (String p : new String[] {"ctx/", "wb/", "lift/world/", "lift/prov/", "lift/cls/", "drop-", "other-", "then-"})
            for (Object o : all()) if (((String) ((Map<String, Object>) o).get("name")).startsWith(p)) total++;
        assertEquals(all().size(), total);
    }

    /** The W-B context shape rule directly (package-private): null = well-formed, else the exact reason. */
    @Test
    void contextErrorExact() {
        Map<String, Object> ok = new LinkedHashMap<>();
        ok.put("intent_session", new LinkedHashMap<>());
        assertNull(IntentWB.contextError(ok));
        Map<String, Object> m = new LinkedHashMap<>(ok);
        m.put("artifacts", null);
        assertEquals("artifacts must be an object", IntentWB.contextError(m));
        m = new LinkedHashMap<>(ok);
        m.put("policy", null);
        assertEquals("policy must be an object", IntentWB.contextError(m));
        m = new LinkedHashMap<>(ok);
        m.put("artifacts", new LinkedHashMap<>(Map.of("labels", "x")));
        assertEquals("artifacts.labels must be an array", IntentWB.contextError(m));
        m.put("artifacts", new LinkedHashMap<>(Map.of("verdicts", 1L)));
        assertEquals("artifacts.verdicts must be an array", IntentWB.contextError(m));
        m.put("artifacts", new LinkedHashMap<>(Map.of("facts", Map.of())));
        assertEquals("artifacts.facts must be an array", IntentWB.contextError(m));
        m.put("artifacts", new LinkedHashMap<>(Map.of("offer_set", List.of())));
        assertEquals("artifacts.offer_set must be an object", IntentWB.contextError(m));
        m = new LinkedHashMap<>(ok);
        m.put("policy", new LinkedHashMap<>(Map.of("provenance", List.of())));
        assertEquals("policy.provenance must be an object", IntentWB.contextError(m));
        m.put("policy", new LinkedHashMap<>(Map.of("world", "x")));
        assertEquals("policy.world must be an object", IntentWB.contextError(m));
        m.put("policy", new LinkedHashMap<>(Map.of("classifiers", Map.of())));
        assertEquals("policy.classifiers must be an array", IntentWB.contextError(m));
    }
}
